import sys
from collections import Counter


def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    s = int(data[1])
    a = sorted(int(x) for x in data[2:2 + n])
    lo = 0
    hi = n - 1
    best = abs(a[0] + a[1] - s)
    while lo < hi:
        t = a[lo] + a[hi]
        d = t - s
        if d < 0:
            d = -d
        if d < best:
            best = d
        if t == s:
            break
        if t < s:
            lo += 1
        else:
            hi -= 1
    cnt = Counter(a)

    def pairs_with_sum(target: int) -> int:
        tot = 0
        for v, c in cnt.items():
            w = target - v
            if w < v:
                continue
            if w == v:
                tot += c * (c - 1) // 2
            else:
                cw = cnt.get(w)
                if cw is not None:
                    tot += c * cw
        return tot

    total = pairs_with_sum(s - best)
    if best > 0:
        total += pairs_with_sum(s + best)
    sys.stdout.write("%d %d\n" % (best, total))


main()

