import sys
from bisect import bisect_left, bisect_right

data = sys.stdin.read().split()
n = int(data[0])
s = int(data[1])
a = [int(x) for x in data[2:2 + n]]
if n <= 1500:
    # exhaustive: every unordered pair
    best = None
    cntpairs = 0
    for i in range(n):
        for j in range(i + 1, n):
            d = a[i] + a[j] - s
            if d < 0:
                d = -d
            if best is None or d < best:
                best = d
                cntpairs = 1
            elif d == best:
                cntpairs += 1
    print(best, cntpairs)
else:
    # same answer by binary search on the sorted roll instead of a sweep
    b = sorted(a)
    best = None
    for i in range(n):
        need = s - b[i]
        pos = bisect_left(b, need)
        for k in range(pos - 2, pos + 3):
            if 0 <= k < n and k != i:
                d = b[i] + b[k] - s
                if d < 0:
                    d = -d
                if best is None or d < best:
                    best = d

    def count(target):
        tot = 0
        for i in range(n):
            w = target - b[i]
            lo = bisect_left(b, w, i + 1)
            hi = bisect_right(b, w, i + 1)
            tot += hi - lo
        return tot

    total = count(s - best)
    if best > 0:
        total += count(s + best)
    print(best, total)
